---ReloadPoolObjGO
---@param resPath string
---@param fatherRoot UnityEngine.RectTransform
---@return UnityEngine.GameObject
function UIBattlingTools.ReloadPoolObjGO(resPath, fatherRoot)
    local go = PoolManager:GetNew(resPath, true) or PoolManager:GetNew(resPath, true, 1)
    if not IsNull(fatherRoot) then
        KTool.SetParent(go, fatherRoot.gameObject)
    end
    go.transform.localPosition = Vector3.zero
    return go
end

---ReloadPTCOfBattling
---@param resPath string
---@param goFatherRoot UnityEngine.RectTransform
---@param loopTime number
---@param nativeScale boolean
---@return UnityEngine.GameObject
function UIBattlingTools.ReloadPTCOfBattling(resPath, goFatherRoot, loopTime, nativeScale)
    --- 生成预制体
    local go = PoolManager:GetNew(resPath, false) or PoolManager:GetNew(resPath, false, 1)
    if not IsNull(goFatherRoot) then
        KTool.SetActive(goFatherRoot.gameObject, true)
        KTool.SetParent(go, goFatherRoot.gameObject)
    end
    go.transform.localPosition = Vector3.zero
    go.transform.localScale = IsNull(nativeScale) and Vector3.New(1.5, 1.5, 1) or Vector3.one
    --- 生成组件
    local particlePlayer = go:EnsureComponent(typeof(ParticlePlayer))
    particlePlayer.lifecycleControl = CS.Game.Native.LifecycleControl.Manual
    particlePlayer.lifeTime = loopTime
    particlePlayer.endActionType = CS.Game.Native.EndActionType.Deactivate
    particlePlayer.activateOnPlay = true
    --- 回收的回调函数
    particlePlayer.OnEnd = function()
        UIBattlingTools.RecyclePoolObj(go)
    end
    KTool.SetActive(go, true)
    return go
end

---RecyclePoolObj
---@param go UnityEngine.GameObject
function UIBattlingTools.RecyclePoolObj(go, notClear)
    notClear = true
    if IsNull(go) then return end
    if notClear then
        PoolManager:GiveBack(go)
    else
        PoolManager:GiveBack(go, POOL_MAX)
    end
end

