---CreateGameObjectOfResourceModule
---创建游戏物体
---@param resPath string 游戏预设路径
function UIBattlingTools.CreateGameObjectOfResourceModule(resPath)
    local goFatherRoot = UIBattlingObjRoot.GetRootTrans()
    return UIBattlingTools.CreateGameObjectOfResourceModuleWithRoot(resPath, goFatherRoot)
end

---CreateGameObjectOfResourceModuleWithRoot
---@param resPath string ResPath
---@param rootFather UnityEngine.Transform
function UIBattlingTools.CreateGameObjectOfResourceModuleWithRoot(resPath, rootFather)
    local go = UIBattlingTools.SyncLoadGameObjectByResourceModule(resPath, rootFather)
    if not IsNull(go) then
        local rectTransform = go:GetComponent(typeof(RectTransform))
        if not IsNull(rectTransform) then
            rectTransform.anchoredPosition = Vector2.New(9999, 9999)
        end
    end
    return go
end

--- 同步加载游戏物体
---@param resPath string 资源路径
---@param rootFather UnityEngine.Transform 父物体
function UIBattlingTools.SyncLoadGameObjectByResourceModule(resPath, rootFather)
    local go
    local loader = ResourceModule.LoadBundleSync(resPath, nil, true)
    if loader.IsSuccess then
        if isNull(rootFather) then
            go = loader:Instantiate()
        else
            go = loader:Instantiate(rootFather.transform)
        end
    end
    loader:Release()
    return go
end

---CreateMultiGameObject
---创建多个 游戏相同物体
---@param pGO UnityEngine.GameObject 需要克隆的游戏物体
---@param num integer @ 数量
function UIBattlingTools.CreateMultiGameObject(pGO, num)
    local resultArr = {}
    for i = 1, num do
        local go = GameObject.Instantiate(pGO)
        if not IsNull(go) then
            local rectTransform = go:GetComponent(typeof(RectTransform))
            if not IsNull(rectTransform) then
                rectTransform.anchoredPosition = Vector2.New(9999, 9999)
            end
        end
        table.insert(resultArr, go)
    end
    return resultArr
end

