---GetSkillDescInBattle
---@param skillId number 技能 Id
---@param skillStar number 技能星级
function UIBattlingTools.GetSkillDescInBattle(skillId, skillStar, rare, isSpecial)
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)
    local star = skillCardVo.skillType == 3 and CardConfMgr:GetInstance():GetFinalSkillDisplayLevel(skillStar) or skillStar
    local skillDescInfo = CardUtils.ParseSkillDescBySkillId(skillId, star, star, rare, isSpecial)
    local desc = skillDescInfo[star] or skillDescInfo[1]
    return desc
end

--- 获取技能的伤害类型描述
---@param skillId any
---@param skillStar any
function UIBattlingTools.GetSkillDamageTypeDescInBattle(skillId, skillStar)
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)
    local star = skillCardVo.skillType == 3 and CardConfMgr:GetInstance():GetFinalSkillDisplayLevel(skillStar)  or skillStar
    local finalSkillStar = skillCardVo.skillType == 3 and CardConfMgr:GetInstance():GetFinalSkillDisplayLevel(skillStar)  or -1
    local spDesc = skillCardVo[string.format("damageTypeDesc_%s", checkString(star))]
    if isNull(spDesc) then
        return ""
    end
    local desc = table.concat(CardUtils.GetStarDescList(skillCardVo, spDesc, star, star, finalSkillStar))
    return string.gsub(desc, "\\n", "\n")
end

