---GetAnimatorCurrentFrame
---@param animator UnityEngine.Animator
---@param currentTime number
function UIBattlingTools.GetAnimatorCurrentFrame(animator, currentTime)
    --- 动画总时长
    local length = animator:GetCurrentAnimatorClipInfo(0)[0].clip.length
    --- 动画帧率
    local frameRate = animator:GetCurrentAnimatorClipInfo(0)[0].clip.frameRate
    --- 动画帧率 总帧数
    local totalFrame = length / (1 / frameRate)
    return math.floor(totalFrame * currentTime)
end

---FillCharactorMapAttr
---填充人物属性信息
---@param data table
---@return table
function UIBattlingTools.FillCharactorMapAttr(data)
    local mapAttr = {}
    local l = string.slice(data, "&")
    for i, v in ipairs(l) do
        local d = string.slice(v, "=")
        local key = tonumber(d[1])
        mapAttr[key] = tonumber(d[2])
    end
    return mapAttr
end

