---SetPTCOrderInLayer
---设置 UIPTC 的 OIL
---@param go UnityEngine.GameObject 粒子GO
---@param numOrderInLayer number OIL值
function UIBattlingTools.SetPTCOrderInLayer(go, numOrderInLayer)
    if IsNull(go) then
        return
    end
    local orderInLayerCtrl = KTool.GetOrAddComponent(go, typeof(CS.ParticleOrderController))
    orderInLayerCtrl:SetOrder(numOrderInLayer or 1)
end

---SetGOTrailRendererChildrenLayer
---设置 游戏物体 子节点 轨迹渲染器层级
---@param go UnityEngine.GameObject
---@param numOrderInLayer number
function UIBattlingTools.SetGOTrailRendererChildrenLayer(go, numOrderInLayer)
    if IsNull(go) then
        return
    end
    local compTRs = go:GetComponentsInChildren(typeof(CS.UnityEngine.TrailRenderer))
    if compTRs.Length > 0 then
        for i = 0, compTRs.Length - 1 do
            compTRs[i].sortingOrder = numOrderInLayer
        end
    end
end

function UIBattlingTools.PairsInOrder(tableOrigin)
    local listOrder = {}
    for k, v in pairs(tableOrigin) do
        table.insert(listOrder, k)
    end
    table.sort(listOrder)
    local i = 0
    return function()
        i = i + 1
        local id = listOrder[i]
        return id, tableOrigin[id]
    end
end

