function UIBattlingTools.GetSkillCardPosOutOfRange(pos)
    local NODE_TRANS_EDGE_TOP = 300 --技能卡 屏幕移动边界 上
    local NODE_TRANS_EDGE_BOTTOM = -205 --技能卡 屏幕移动边界 下
    local NODE_TRANS_EDGE_LEFT = -500 --技能卡 屏幕移动边界 左
    local NODE_TRANS_EDGE_RIGHT = 420 --技能卡 屏幕移动边界 右
    local posX = pos.x
    local posY = pos.y
    return posX >= NODE_TRANS_EDGE_RIGHT or posX <= NODE_TRANS_EDGE_LEFT 
            or posY >= NODE_TRANS_EDGE_TOP or posY <= NODE_TRANS_EDGE_BOTTOM
end

function UIBattlingTools.RMUIPage(idDialog)
    xTry(function()
        local listPage = UIModule.Instance.uiPages
        if listPage.Count <= 0 then return end
        for i = listPage.Count - 1, 0, -1 do
            local uiPage = listPage[i]
            local pageA = uiPage.uiArguments
            if uiPage.uiArguments.Count <= 0 then return end
            for i = uiPage.uiArguments.Count - 1, 0, -1 do
                if pageA[i].id == idDialog then
                    return pageA:RemoveAt(i)
                end
            end
        end
    end)
end

function UIBattlingTools.WorldPointToUIPoint(position, rootFather, cam)
    local mainCamera = cam or CS.Game.Native.URP.URPCameraController.Instance.mainCamera
    local screenPoint = mainCamera:WorldToScreenPoint(position)
    local uiCamera = CS.Game.Native.URP.URPCameraController.Instance.uiCamera
    local v2 = Vector2.New(screenPoint.x, screenPoint.y)
    return UIBattlingTools.ScreenPointToLocalPointInRectangle(v2, rootFather, uiCamera)
end

function UIBattlingTools.ScreenPointToLocalPointInRectangle(position, rootFather, cam)
    local _camera = cam or URPCameraController.mainCamera
    --local rectTrans = KTool.GetComponent(rootFather.gameObject, typeof(RectTransform))
    local bool, vec2 = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(rootFather, position, _camera, nil)
    return vec2
end

function UIBattlingTools.AddCanvasComponent(go, layer)
    local canvas = KTool.GetOrAddComponent(go, typeof(CS.UnityEngine.Canvas))
    KTool.GetOrAddComponent(go, typeof(CS.UnityEngine.UI.GraphicRaycaster))
    if layer then
