function UIBattlingTools.GetAnimationClip(go, strNameClip)
    local animator = go.gameObject:GetComponent(typeof(Animator))
    if IsNull(animator) then return nil end
    local clips = animator.runtimeAnimatorController.animationClips
    for i = 1, clips.Length do
        local clip = clips[i - 1]
        if clip.name == checkString(strNameClip) then
            return clip
        end
    end
    return nil
end

function UIBattlingTools.GetAnimationTime(animator, animationName)
    local animatorComp = animator.gameObject:GetComponent(typeof(Animator))
    if IsNull(animatorComp) then return 0 end
    local clips = animatorComp.runtimeAnimatorController.animationClips
    for i = 1, clips.Length do
        local curAnimation = clips[i - 1]
        if curAnimation.name == animationName then  
            return checkNumber(curAnimation.length)
        end
    end
    return 0
end

function UIBattlingTools.GetRestraintElement(element)
    local restrainList = {}
    local berestrainList = {}
    element = checkNumber(element)
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting261)
    local length = tableFile:GetRowCount()
    for i = 1, length do
        local row = tableFile:GetRow(i)
        local elementId = checkNumber(row:Get('elementId'))
        local restrainElementId = checkNumber(row:Get('restraintElementId'))
        local damageChange = checkNumber(row:Get('damagePara'))
        -- if elementId == element then
        --     if damageChange > 0 then
        --         table.insert(restrainList, restrainElementId)
        --     elseif damageChange < 0 then
        --         table.insert(berestrainList, restrainElementId)
        --     end
        -- end
        if restrainElementId == element then
            if damageChange > 0 then
                table.insert(berestrainList, elementId)
            elseif damageChange < 0 then
                table.insert(restrainList, elementId)
            end
        end
    end
    return restrainList, berestrainList
end

