function UIBattlingTools.SinMove(go, pos1, pos2, time, cbFun)
    local circle = 0.13
    local maxPos = 1
    local minPos = -1
    local TAG_TWEEN = "GUIDE_SIN_MOVE"
    local tween = DOTween.To(function() return 0 end,
            function(updateValue)
                xTry(function()
                    local position = CS.UnityEngine.Vector3.Lerp(pos1, pos2, updateValue)
                    local innner = (2 * math.pi) * circle
                    local ya = math.sin(innner * position.x)
                    local maall = (maxPos - minPos) * 0.5
                    local middle = maall + minPos;
                    local y = middle + maall * ya
                    go.transform.position = Vector3.New(position.x, position.y + y, position.z)
                end)
            end, 1, time)
    tween.onComplete = function()
        if cbFun then
            cbFun()
        end
    end
    tween.stringId = TAG_TWEEN
    return tween
end

