function UIBattlingTools.Remap(value, from1, to1, from2, to2)
    return (value - from1) / (to1 - from1) * (to2 - from2) + from2
end

--- 根据关卡类型获取页面跳转的模式
---@param questType number 关卡类型 Constants.IDType
function UIBattlingTools.GetUIDialogJumpMode(questType)
    local jumpMode = 0
    if questType == Constants.IDType.QuestMapDecryptionTracking
        or questType == Constants.IDType.QuestMapDecryptionMap then
        jumpMode = 1
    elseif questType == Constants.IDType.Fairyland then
        jumpMode = 3
    else
        jumpMode = 2
    end
    return jumpMode
end

--- 卡牌变化时用于判断是否只有星级发生改变
---@param oldState table 旧状态
---@param newState table 新状态
function UIBattlingTools.IsOnlyStarChanged(oldState, newState)
    local onlyStarChanged = true
    onlyStarChanged = onlyStarChanged and oldState.roleId == newState.roleId
    onlyStarChanged = onlyStarChanged and oldState.skillId == newState.skillId
    onlyStarChanged = onlyStarChanged and oldState.skillIndex == newState.skillIndex
    onlyStarChanged = onlyStarChanged and oldState.star ~= newState.star
    return onlyStarChanged
end

