--- 获取卡牌信息
---@param roleIndex integer @ 角色战场id
---@param playerCardId integer @ 卡牌id
---@param teamId integer @ 主线机器人队伍id（默认值 nil）
function UIBattlingTools:GetCardInfo(roleIndex, playerCardId, teamId)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local playerCardId = checkInt(playerCardId)
    if playerCardId > 0 then
        -- 玩家卡牌id大于0
        local cardDojo = cardComponent:GetCardById(playerCardId)
        if isNull(cardDojo) then
            -- 有可能是队友的卡牌
            local roleData = UIBattlingDataMgr:GetRoleDataByRoleId(roleIndex)
            cardDojo = {
                cardSkin = roleData.skinId,
                cardId = roleData.cardId,
                star = roleData.star,
                cardLevel = roleData.level,
                advanceLevel = roleData.advanceLevel,
            }
        end
        return checkTable(cardDojo)
    else
        -- 机器人卡牌id小于0
        local cardId = checkTable(UIBattlingDataMgr:GetCharactorDataById(roleIndex)).cardId
        local mainHelper = BattleHelperConfMgr:GetInstance():GetMainLevelHelper(teamId, cardId)
        
        -- local keyMazeHelper = math.abs(playerCardId)
        -- local mazeHelper = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", keyMazeHelper)

        -- local robVo = mainHelper or mazeHelper

        local isRob = not isNull(mainHelper)
        return isRob and mainHelper or checkTable(cardComponent:GetCardById(playerCardId))
    end
end

