--- 把总的百分比血量转换为多条模式下的条数和百分比
---@param curTotalProgress any 总的百分比血量
---@param multiNum any 多条的条数
function UIBattlingTools.HP2MultiMode(curTotalProgress, multiNum)
    local perNumProgress = (1 / multiNum)
    local p = curTotalProgress / perNumProgress
    local curNum = math.floor(p)    -- 有几条满的血
    local curProgress = p - curNum  -- 最上面一条不满的血的百分比

    local showNum, showProgress
    if curProgress > 0 then
        showNum = curNum + 1    -- 满的条数 + 最上面不满的一条
        showProgress = curProgress
    else
        if curNum == 0 then
            showNum = 0
            showProgress = 0
        else
            -- 最上面为0的一条，转换为吓一跳的满进度
            showNum = curNum
            showProgress = 1
        end
    end
    
    return showNum, showProgress
end


