--- 歼灭战模式获取玩家数据
---@param isMySelf integer 1 = 我自己 2 = 我队友
function UIBattlingTools.PPVEGetPlayersData(isMySelf)
    if BattleInfo and BattleInfo.initData then
        local initData = BattleInfo.initData
        local myPlayerId = initData.selfId
        local playersData = initData.playerTeam[1]
        local result = {}
        if isMySelf == 1 then
            for i, v in ipairs(playersData) do
                if v.playerId == myPlayerId then
                    table.insert(result, v)
                end
            end
        else
            for i, v in ipairs(playersData) do
                if v.playerId ~= myPlayerId then
                    table.insert(result, v)
                end
            end
        end
        return result
    end
    return nil
end

return UIBattlingTools